+impl SafeListenerWrapper<IEwsMessageSyncListener> {
+    /// Convert types and forward to
+    /// [`IEwsMessageSyncListener::OnMessageCreated`].
+    pub fn on_message_created<S: AsRef<str>>(
+        &self,
+        message_id: S,
