+    }
+
+    /// A safe wrapper for [`nsIMsgDBHdr::SetPriority`].
+    fn set_priority(&self, priority: nsMsgPriorityValue) -> Result<(), nsresult> {
+        // SAFETY: nsMsgPriorityValues are safe to use across the Rust/C++
